// Normaliza payload da Evolution API
const body = $input.first().json.body;
const data = body.data || {};

const phone = data.key?.remoteJid?.replace('@s.whatsapp.net', '') || '';
const text  = (data.message?.conversation || '').toLowerCase().trim();

return [{ json: { phone, text, rawText: data.message?.conversation || '' } }];

// Mescla dados da mensagem com estado da sessão
const msg = $('Normalizar mensagem').first().json;
const sessions = $input.first().json;
const session = Array.isArray(sessions) && sessions.length > 0
  ? sessions[0]
  : { phone: msg.phone, step: 'INIT' };

return [{ json: { ...msg, session } }];

// Etapa INIT: Detecta se é cancelamento ou novo agendamento
const text = $json.text;
const phone = $json.phone;

if (text.includes('cancelar') || text.includes('cancela') || text.includes('desmarcar')) {
  return [{ json: { phone, action: 'cancel_lookup', reply: null } }];
}

// Apresenta menu
const menu = `Oi! Sou o assistente do *Studio da Michele* 💅\n\nQual serviço você quer fazer, meu bem?\n\n1. Esmaltação Completa (1h30) - R$40\n2. Pé Normal (40min) - R$25\n3. Mão Normal (45min) - R$20\n4. Banho de Gel (2h30) - R$80\n5. Alongamento em Gel (3h) - R$120\n\nResponda o número ou nome do serviço 😊`;
return [{ json: { phone, action: 'send_menu', reply: menu, nextStep: 'WAITING_SERVICE' } }];

// Etapa WAITING_SERVICE: Identifica serviço pelo texto
const text = $json.text;
const phone = $json.phone;

const SERVICE_MAP = [
  { id: 1, patterns: ['esmalte', 'esmaltacao', 'esmaltação', 'completa', '1'] },
  { id: 2, patterns: ['pe', 'pé', 'pezinho', '2'] },
  { id: 3, patterns: ['mao', 'mão', 'maozinha', 'mãozinha', '3'] },
  { id: 4, patterns: ['gel', 'banho', 'banho de gel', '4'] },
  { id: 5, patterns: ['alongamento', 'fibra', 'unhas de fibra', '5'] },
];

const found = SERVICE_MAP.find(s => s.patterns.some(p => text.includes(p)));

if (!found) {
  return [{ json: {
    phone,
    action: 'send_message',
    reply: 'Não entendi qual serviço 😅 Responda o número (1 a 5) ou o nome do serviço!',
    nextStep: 'WAITING_SERVICE',
    serviceId: null
  }}];
}

const DAYS_PT = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
const today = new Date();
const dates = [];
for (let i = 0; i < 60 && dates.length < 7; i++) {
  const d = new Date(today);
  d.setDate(today.getDate() + i);
  if (d.getDay() !== 0 && d.getDay() !== 6) {
    const dd = String(d.getDate()).padStart(2,'0');
    const mm = String(d.getMonth()+1).padStart(2,'0');
    dates.push({ iso: `${d.getFullYear()}-${mm}-${dd}`, label: `${DAYS_PT[d.getDay()]} ${dd}/${mm}` });
  }
}

const datesText = dates.map((d,i) => `${i+1}. ${d.label}`).join('\n');
const reply = `Certo! Para qual data?\n\n${datesText}\n\nResponda o número ou escreva a data (ex: segunda, amanhã, 25/05) 😊`;

return [{ json: { phone, action: 'send_message', reply, nextStep: 'WAITING_DATE', serviceId: found.id, availableDates: dates } }];

// Etapa WAITING_DATE: Interpreta data informada e busca slots
const text    = $json.text;
const phone   = $json.phone;
const session = $json.session;

const DAYS_PT = { 'segunda':1,'seg':1,'terca':2,'terça':2,'ter':2,'quarta':3,'qua':3,'quinta':4,'qui':4,'sexta':5,'sex':5,'amanha':1,'amanhã':1 };

let targetDate = null;
const today = new Date();
today.setHours(0,0,0,0);

// Tenta número (posição na lista)
const num = parseInt(text, 10);
if (!isNaN(num) && num >= 1) {
  let count = 0;
  for (let i = 0; count < num; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    if (d.getDay() !== 0 && d.getDay() !== 6) count++;
    if (count === num) { targetDate = d; break; }
  }
}

// Tenta DD/MM
if (!targetDate) {
  const m = text.match(/(\d{1,2})[\/\-](\d{1,2})/);
  if (m) {
    const d = new Date(today.getFullYear(), parseInt(m[2])-1, parseInt(m[1]));
    if (d >= today) targetDate = d;
  }
}

// Tenta nome do dia
if (!targetDate) {
  const clean = text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const dowTarget = Object.entries(DAYS_PT).find(([k]) => clean.includes(k))?.[1];
  if (dowTarget !== undefined) {
    const diff = clean.includes('amanha') || clean.includes('amanhã') ? 1 : null;
    if (diff !== null) {
      targetDate = new Date(today);
      targetDate.setDate(today.getDate() + diff);
    } else {
      for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        if (d.getDay() === dowTarget) { targetDate = d; break; }
      }
    }
  }
}

if (!targetDate || targetDate.getDay() === 0 || targetDate.getDay() === 6) {
  return [{ json: { phone, action: 'send_message', reply: 'Não entendi a data 😅 Escreva assim: _segunda_, _terça_, ou _25/05_. Só dias úteis!', nextStep: 'WAITING_DATE', serviceId: session.service_id } }];
}

const yyyy = targetDate.getFullYear();
const mm   = String(targetDate.getMonth()+1).padStart(2,'0');
const dd   = String(targetDate.getDate()).padStart(2,'0');
const iso  = `${yyyy}-${mm}-${dd}`;

return [{ json: { phone, action: 'fetch_slots', isoDate: iso, serviceId: session.service_id || null } }];

// Etapa WAITING_SLOT: Identifica horário escolhido
const text    = $json.text;
const phone   = $json.phone;
const session = $json.session;

// Tenta extrair HH:MM ou "9h", "13h", "13:30"
const m1 = text.match(/(\d{1,2})[:h](\d{2})?/);
let slot = null;
if (m1) {
  const h = m1[1].padStart(2,'0');
  const min = m1[2] || '00';
  slot = `${h}:${min}`;
}

if (!slot) {
  return [{ json: { phone, action: 'send_message', reply: 'Não entendi o horário 😅 Responda assim: _09:00_, _13h_, _15:30_', nextStep: 'WAITING_SLOT', serviceId: session.service_id, isoDate: session.date } }];
}

return [{ json: { phone, action: 'send_message', reply: 'Perfeito! Só me diz seu nome completo 😊', nextStep: 'WAITING_NAME', serviceId: session.service_id, isoDate: session.date, slotTime: slot + ':00' } }];

// Etapa WAITING_NAME: Recebe nome e confirma agendamento
const name    = $json.rawText?.trim() || $json.text?.trim() || '';
const phone   = $json.phone;
const session = $json.session;

if (name.split(' ').length < 2 || name.length < 4) {
  return [{ json: { phone, action: 'send_message', reply: 'Pode me dizer seu nome completo? (Nome e Sobrenome)', nextStep: 'WAITING_NAME', serviceId: session.service_id, isoDate: session.date, slotTime: session.slot_time } }];
}

return [{ json: {
  phone,
  action: 'create_appointment',
  clientName: name,
  serviceId: session.service_id,
  isoDate:   session.date,
  slotTime:  session.slot_time
} }];

// Formata lista de slots e monta resposta
const data    = $input.first().json;
const prev    = $('Handle WAITING_DATE').first().json;
const slots   = Array.isArray(data) ? data.map(s => s.slot_time?.slice(0,5)) : [];

const DAYS_PT = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const MONTHS_PT = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
const d = new Date(prev.isoDate + 'T12:00:00');
const dateLabel = `${DAYS_PT[d.getDay()]} ${d.getDate()} de ${MONTHS_PT[d.getMonth()]}`;

if (slots.length === 0) {
  return [{ json: {
    phone: prev.phone,
    action: 'send_message',
    reply: `Poxa, não tenho horários disponíveis para ${dateLabel} 😕\nEscolha outra data:`,
    nextStep: 'WAITING_DATE',
    serviceId: prev.serviceId
  }}];
}

const slotsText = slots.join(' | ');
const reply = `Certo! Para ${dateLabel}, tenho esses horários disponíveis:\n\n🕐 ${slotsText}\n\nQual você prefere?`;

return [{ json: {
  phone: prev.phone,
  action: 'send_message',
  reply,
  nextStep: 'WAITING_SLOT',
  serviceId: prev.serviceId,
  isoDate: prev.isoDate
} }];

// Monta mensagem de confirmação após agendamento criado
const prev = $('Handle WAITING_NAME').first().json;

const DAYS_PT   = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const MONTHS_PT = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
const d = new Date(prev.isoDate + 'T12:00:00');
const dateLabel = `${DAYS_PT[d.getDay()]} ${d.getDate()} de ${MONTHS_PT[d.getMonth()]}`;

// Mapeia id → nome do serviço
const SERVICES = { 1:'Esmaltação Completa', 2:'Pé Normal', 3:'Mão Normal', 4:'Banho de Gel', 5:'Alongamento em Gel' };
const PRICES   = { 1:'R$40', 2:'R$25', 3:'R$20', 4:'R$80', 5:'R$120' };
const DURATIONS = { 1:90, 2:40, 3:45, 4:150, 5:180 };

const svcName = SERVICES[prev.serviceId] || 'Serviço';
const price   = PRICES[prev.serviceId] || '';
const dur     = DURATIONS[prev.serviceId] || 0;
const [h,m]   = prev.slotTime.split(':').map(Number);
const endMin  = h*60+m+dur;
const endStr  = `${String(Math.floor(endMin/60)).padStart(2,'0')}:${String(endMin%60).padStart(2,'0')}`;
const startStr = prev.slotTime.slice(0,5);

const firstName = prev.clientName.split(' ')[0];

const reply = `Agendado, ${firstName}! ✅\n\n📅 ${dateLabel}\n🕐 ${startStr} → ${endStr}\n✨ ${svcName}\n💰 ${price}\n\nVou te lembrar 2 dias antes, tá? 💅`;

return [{ json: { phone: prev.phone, action: 'send_message', reply, nextStep: null, clearSession: true } }];

// Unifica mensagem final de todas as etapas para envio
// Recebe de: n8, n9, n14, n16 (rotas variadas)
const items = $input.all();
return items;

// Salva/atualiza estado da sessão no Supabase
const d = $input.first().json;
if (!d.nextStep && !d.clearSession) return [];

const body = {
  phone:      d.phone,
  step:       d.clearSession ? 'INIT' : d.nextStep,
  service_id: d.serviceId  || null,
  date:       d.isoDate    || null,
  slot_time:  d.slotTime   || null,
  name:       d.clientName || null
};

return [{ json: body }];
